    let len = buf.length;
    let ws  = "";
    for (let offset = 0; offset < len; offset++) {
        let n = buf.readUInt8(offset);
        let c = "";
        for (let i = 0; i < 8; i++) {
            c = (n & 1 ? TAB : SPACE) + c;
            n = n >>> 1;
        }
        ws += c;
    }
    return ws + LF;
}

end();

