var adapter = {
  resolved: Promise.resolve,
  rejected: Promise.reject,
  deferred: function() {
    var resolveFn, rejectFn;
    var p = new Promise(function(resolve, reject) {
      resolveFn = resolve;
      rejectFn = reject;
    });
