    if (!url) {
        return Promise.reject(new Error('Request was not given a url.'));
    } else if (!url.match(/^http/)) {
        apiUrl = ApiUrls[url];
        if (!apiUrl) {
            return Promise.reject(new Error(`Request could not find a url mapping for "${url}"`));
        }
    }

    return baseRequest(apiUrl, requestConfig)
        .then((res) => res.json())
        .catch((err) => {
            console.error(err);
            throw err;
        });
}

