class TestTask extends Task {

    constructor(buildManager) {
        super(buildManager);
        this.command = "test";
        let extension = null;
        if (this._buildManager.options.typescript) {
            require('ts-node/register');
            extension = 'ts';
        } else {
            require('babel-core/register');
            extension = 'js';
