    fileService,
    Promise
) {

    function start() {
        return core.start()
            .then(function() {
                return Promise.all([profiles.load(), templates.load()]);
            })
            .then(function() {
                app.use('/api/common', router);
                app.use('/api/current', router);
                app.use('/api/1.1', router);

                return fileService.start(configuration.get("fileService"));
            })
            .then(function() {
                app.listen();
            });
    }

    function stop() {
        return Promise.resolve()
            .then(function() {
                return app.close();
            })
            .then(function() {
                return core.stop();
            });
    }

    return {
        start: start,
        stop: stop
    };
}

