function parse(line) {
  if (LESS_VARIABLE_REGEX.test(line)) {
    const [all, variable, separator, value] = LESS_VARIABLE_REGEX.exec(line)
    return {
      variable,
      value
    }
  }
  return null
}

module.exports = {
  parse
}

