            var h = $(e.target)[0].scrollHeight; // size of all content

            if ((y + vH) >= h) {
                navigation.goNext();
            } else if (y <= 0 && prev > 0) {
                navigation.goPrev();
            }

            prev = y;
        });
    });
});

