    }

    minus(v) {
        return new Vec(this.x - v.x, this.y - v.y);
    }

    get length() {
        return Math.sqrt(this.x**2 + this.y**2);
    }

    toString() {
        return `Vec{x: ${this.x}, y: ${this.y}}`;
    }
}

