      cursor: 'default'
    };

    return (
      <li
        style={style}
        onClick={this.toggleCompleted}
      >
        {this.props.text}
      </li>
    );
  }

  toggleCompleted = (event) => {
    this.setState({ completed: !this.state.completed });
  }
}

