  $.ajax(options).pipe(function(data) {dfr.resolve(data);}, function(jqXhr) {
    if (retries > 0) {
      setTimeout(doAjax, 100, options, retries - 1, dfr);
    } else {
      dfr.reject(jqXhr);
    }
  });
}

