export function lerp( a, b, t ) {
  return a + t * ( b - a );
}

export function inverseLerp( a, b, x ) {
  return ( x - a ) / ( b - a );
}

export function map( x, a, b, c, d ) {
  return lerp( c, d, inverseLerp( a, b, x ) );
}

