			})
			.error(function(err) {
				$scope.results = err;
			});
	}

	$scope.clickElement = function (element) {
		element.count += 1;
		var promiseElement = $http.put('/elements/' + element.id, element)
		promiseElement.then(function(elem) {
			$scope.results[element.id] = elem;
		})
	};
});

